/**
 * Insert PrusaSlicer-style thumbnail blocks into an ASCII G-code file.
 * The CLI cannot render previews (no OpenGL), so the browser renders them and the
 * server writes them right after the "; generated by" header line:
 *
 *   ;
 *   ; thumbnail_QOI begin 313x173 12345
 *   ; <base64, 78 chars per line>
 *   ; thumbnail_QOI end
 *   ;
 */
import fs from 'node:fs';
import path from 'node:path';
import type { ThumbnailFormat, ThumbnailInput } from '@webslicer/shared';

const TAGS: Record<ThumbnailFormat, string> = { PNG: 'thumbnail', JPG: 'thumbnail_JPG', QOI: 'thumbnail_QOI' };

export function thumbnailBlock(t: ThumbnailInput): string {
  const tag = TAGS[t.format] || 'thumbnail';
  const b64 = t.data.replace(/\s+/g, '');
  const lines: string[] = [';', `; ${tag} begin ${t.width}x${t.height} ${b64.length}`];
  for (let i = 0; i < b64.length; i += 78) lines.push(`; ${b64.slice(i, i + 78)}`);
  lines.push(`; ${tag} end`, ';');
  return lines.join('\n') + '\n';
}

/** Rewrite `file` with the thumbnail blocks inserted after its first line. */
export async function injectThumbnails(file: string, thumbs: ThumbnailInput[]): Promise<void> {
  if (!thumbs.length) return;
  const fd = fs.openSync(file, 'r');
  let firstLineEnd = -1;
  let offset = 0;
  const chunk = Buffer.alloc(8192);
  try {
    while (firstLineEnd < 0) {
      const n = fs.readSync(fd, chunk, 0, chunk.length, offset);
      if (n <= 0) break;
      const idx = chunk.subarray(0, n).indexOf(0x0a);
      if (idx >= 0) firstLineEnd = offset + idx + 1;
      else offset += n;
    }
  } finally {
    fs.closeSync(fd);
  }
  if (firstLineEnd < 0) return;
  const tmp = path.join(path.dirname(file), `.${path.basename(file)}.tmp`);
  const header = fs.readFileSync(file, { encoding: 'utf8', flag: 'r' }).slice(0, 0); // placeholder to keep types simple
  void header;
  const out = fs.createWriteStream(tmp);
  const head = Buffer.alloc(firstLineEnd);
  const fd2 = fs.openSync(file, 'r');
  fs.readSync(fd2, head, 0, firstLineEnd, 0);
  fs.closeSync(fd2);
  out.write(head);
  out.write('\n' + thumbs.map(thumbnailBlock).join(''));
  await new Promise<void>((resolve, reject) => {
    const rest = fs.createReadStream(file, { start: firstLineEnd });
    rest.on('error', reject);
    out.on('error', reject);
    out.on('finish', () => resolve());
    rest.pipe(out);
  });
  fs.renameSync(tmp, file);
}

/** Parse PrusaSlicer's "thumbnails" option ("16x16/QOI, 313x173/QOI" or legacy "16x16, 220x124"). */
export function parseThumbnailSpec(spec: string | undefined, defaultFormat: string | undefined): Array<{ width: number; height: number; format: ThumbnailFormat }> {
  if (!spec) return [];
  const def = (defaultFormat || 'PNG').toUpperCase() as ThumbnailFormat;
  const out: Array<{ width: number; height: number; format: ThumbnailFormat }> = [];
  for (const part of spec.split(',')) {
    const m = /^\s*(\d+)\s*x\s*(\d+)\s*(?:\/\s*([A-Za-z]+))?\s*$/.exec(part);
    if (!m) continue;
    const f = (m[3] || def).toUpperCase();
    out.push({ width: Number(m[1]), height: Number(m[2]), format: f === 'JPG' || f === 'JPEG' ? 'JPG' : f === 'QOI' ? 'QOI' : 'PNG' });
  }
  return out;
}
